
#[cfg(test)]mod fire70_request_development_tests{
    use super::*;
    fn world()->World{let mut w=super::super::native_login::LoginController::default().snapshot().world.clone();let f:serde_json::Value=serde_json::from_slice(include_bytes!(r"D:\lineage開發\3-lito開發\lito重建版\LiTo381-Modern\tests\fixtures\native-world-current.json")).unwrap();for key in ["world","start","status","actor","bot"]{let h=f["packets"][key].as_str().unwrap();w.accept(&(0..h.len()).step_by(2).map(|i|u8::from_str_radix(&h[i..i+2],16).unwrap()).collect::<Vec<_>>()).unwrap();}w.learned_skills.clear();w.learned_skills.insert(70);w.mp=Some([1,100]);w.hp=Some([1,100]);w}
    #[test]fn firestorm_is_selector_only_and_does_not_accept_or_serialize_an_actor(){let w=world();let before=serde_json::to_value(&w).unwrap();assert_eq!(request(&w,70,None).unwrap(),vec![20,8,5]);assert!(request(&w,70,Some(w.own_actor().unwrap().id)).is_err());assert_eq!(reuse_millis(70),2000);assert_eq!(serde_json::to_value(&w).unwrap(),before);}
    #[test]fn native_selection_discards_actor_selection_for_centered_spell_but_keeps_book_mp_guards(){use super::super::native_skill_selection::{Model,Target};let mut w=world();let mut m=Model::default();m.sync(7,&w,true);m.select(Some(70)).unwrap();let t=Target::capture(&w,w.own_actor().unwrap().id).unwrap();assert_eq!(m.choice(7,&w,Some(t)).unwrap().target,None);w.mp=Some([0,100]);assert!(m.choice(7,&w,None).is_err());w.mp=Some([1,100]);w.learned_skills.clear();assert!(request(&w,70,None).is_err());}
    #[test]fn firestorm_S39_requires_type_zero_and_parses_complete_packet_before_world_mutation(){let mut w=world();let a=w.own_actor().unwrap().clone();let mut b=vec![57,18];b.extend(a.id.to_le_bytes());b.extend(a.x.to_le_bytes());b.extend(a.y.to_le_bytes());b.push(3);b.extend(7_u32.to_le_bytes());b.extend(1819_u16.to_le_bytes());b.extend([0,0,0,0,0]);assert_eq!(super::super::native_attack_many::decode(&b).unwrap().unwrap().graphics,1819);let mut wrong=b.clone();wrong[17]=8;assert!(super::super::native_attack_many::decode(&wrong).unwrap().is_none());let before=serde_json::to_value(&w).unwrap();assert!(w.accept(&b[..b.len()-1]).is_err());assert_eq!(serde_json::to_value(&w).unwrap(),before);w.accept(&b).unwrap();assert_eq!(w.many_attacks.last().unwrap().target_origin,None);}
}
